import java.util.Scanner;

public class Main {
    static int[] consumed;
    static int consumedCount;

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int cap = sc.nextInt();
        int k = sc.nextInt();
        int[] items = new int[k];
        for (int i = 0; i < k; i++) {
            items[i] = sc.nextInt();
        }
        consumed = new int[k];
        Buffer buffer = new Buffer(cap);
        Producer p = new Producer(buffer, items);
        Consumer c = new Consumer(buffer, k);
        c.start();
        p.start();
        p.join();
        c.join();
        for (int i = 0; i < k; i++) {
            System.out.println("Consumed: " + consumed[i]);
        }
        System.out.println("Total consumed: " + consumedCount);
    }
}

class Buffer {
    private int[] slots;
    private int count;
    private int head;
    private int tail;

    Buffer(int cap) {
        slots = new int[cap];
        count = 0;
        head = 0;
        tail = 0;
    }

    synchronized void put(int item) {
        while (count == slots.length) {
            try {
                wait();
            } catch (InterruptedException e) {
                // re-check the buffer state after waking up
            }
        }
        slots[tail] = item;
        tail = (tail + 1) % slots.length;
        count = count + 1;
        notifyAll();
    }

    synchronized int take() {
        while (count == 0) {
            try {
                wait();
            } catch (InterruptedException e) {
                // re-check the buffer state after waking up
            }
        }
        int item = slots[head];
        head = (head + 1) % slots.length;
        count = count - 1;
        Main.consumed[Main.consumedCount] = item;
        Main.consumedCount = Main.consumedCount + 1;
        notifyAll();
        return item;
    }
}

class Producer extends Thread {
    private Buffer buffer;
    private int[] items;

    Producer(Buffer buffer, int[] items) {
        this.buffer = buffer;
        this.items = items;
    }

    public void run() {
        for (int i = 0; i < items.length; i++) {
            buffer.put(items[i]);
        }
    }
}

class Consumer extends Thread {
    private Buffer buffer;
    private int total;

    Consumer(Buffer buffer, int total) {
        this.buffer = buffer;
        this.total = total;
    }

    public void run() {
        for (int i = 0; i < total; i++) {
            buffer.take();
        }
    }
}

import java.util.Scanner;

public class Main {
    static int[] data;
    static int chunkSize;
    static long[] chunkSums;
    static long grandTotal = 0;

    static synchronized void merge(int index, long sum) {
        chunkSums[index] = sum;
        grandTotal = grandTotal + sum;
    }

    static class BatchTask implements Runnable {
        private int index;

        BatchTask(int index) {
            this.index = index;
        }

        public void run() {
            long s = 0;
            int start = index * chunkSize;
            for (int j = 0; j < chunkSize; j++) {
                s = s + data[start + j];
            }
            merge(index, s);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        chunkSize = sc.nextInt();
        int n = k * chunkSize;
        data = new int[n];
        for (int i = 0; i < n; i++) {
            data[i] = sc.nextInt();
        }
        chunkSums = new long[k];
        Thread[] workers = new Thread[k];
        for (int i = 0; i < k; i++) {
            workers[i] = new Thread(new BatchTask(i));
            workers[i].start();
        }
        for (int i = 0; i < k; i++) {
            workers[i].join();
        }
        for (int i = 0; i < k; i++) {
            System.out.println("Chunk " + (i + 1) + ": " + chunkSums[i]);
        }
        System.out.println("Grand total: " + grandTotal);
    }
}

import java.util.Scanner;

public class Main {
    static int[] data;
    static int chunkSize;
    static int[] mins;
    static int[] maxs;

    static class MinMaxWorker extends Thread {
        private int index;

        MinMaxWorker(int index) {
            this.index = index;
        }

        public void run() {
            int start = index * chunkSize;
            int lo = data[start];
            int hi = data[start];
            for (int j = 1; j < chunkSize; j++) {
                int v = data[start + j];
                if (v < lo) {
                    lo = v;
                }
                if (v > hi) {
                    hi = v;
                }
            }
            mins[index] = lo;
            maxs[index] = hi;
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Scanner sc = new Scanner(System.in);
        int k = sc.nextInt();
        chunkSize = sc.nextInt();
        int n = k * chunkSize;
        data = new int[n];
        for (int i = 0; i < n; i++) {
            data[i] = sc.nextInt();
        }
        mins = new int[k];
        maxs = new int[k];
        MinMaxWorker[] workers = new MinMaxWorker[k];
        for (int i = 0; i < k; i++) {
            workers[i] = new MinMaxWorker(i);
            System.out.println("Worker " + (i + 1) + " state before start: " + workers[i].getState());
            workers[i].start();
        }
        for (int i = 0; i < k; i++) {
            workers[i].join();
        }
        int gmin = mins[0];
        int gmax = maxs[0];
        for (int i = 0; i < k; i++) {
            System.out.println("Worker " + (i + 1) + " state after join: " + workers[i].getState());
            System.out.println("Worker " + (i + 1) + " range: min " + mins[i] + " max " + maxs[i]);
            if (mins[i] < gmin) {
                gmin = mins[i];
            }
            if (maxs[i] > gmax) {
                gmax = maxs[i];
            }
        }
        System.out.println("Global min: " + gmin);
        System.out.println("Global max: " + gmax);
    }
}
